const sectorOptions=()=>data.sectors.filter(s=>s.id!=='foret').map(s=>[s.id,s.label]).concat([['foret','Forêt de Meudon']]);
function inside(point,ring){let yes=false;for(let i=0,j=ring.length-1;i<ring.length;j=i++){const[xi,yi]=ring[i],[xj,yj]=ring[j];if(((yi>point.lat)!==(yj>point.lat))&&(point.lon<(xj-xi)*(point.lat-yi)/(yj-yi)+xi))yes=!yes;}return yes;}
function sectorFor(point){return point?data.sectors.find(s=>inside(point,s.rings[0]))?.id||'':'';}
